HAPPY_URI = "data:application/json;base64,"
SAD_URI = "data:application/json;base64,"


def test_name_and_symbol(mood_nft):
    assert mood_nft.name() == "MoodNFT"
    assert mood_nft.symbol() == "MOOD"


def test_only_one_token_minted(mood_nft):
    assert mood_nft.number_of_tokens() == 1


def test_token_uri(mood_nft):
    assert mood_nft.tokenURI(0) == SAD_URI
    mood_nft.flip_mood(0)
    assert mood_nft.tokenURI(0) == HAPPY_URI
    mood_nft.flip_mood(0)
    assert mood_nft.tokenURI(0) == SAD_URI
